    open_list = [0] * m
    total_cost = 0.0
    # Sort customers by demand descending (greedy for large demands first)
    cust_indices = sorted(range(n), key=lambda i: customers[i]['demand'], reverse=True)
    for i in cust_indices:
        demand = customers[i]['demand']
        costs = customers[i]['costs']
        # Sort warehouses by increasing assignment cost
        sorted_indices = sorted(range(m), key=lambda j: costs[j])
        for j in sorted_indices:
            if demand <= 0:
                break
            if remaining_cap[j] > 0:
                assign = min(demand, remaining_cap[j])
                assignments[i][j] = assign
                demand -= assign
                remaining_cap[j] -= assign
        if demand > 0:
            # Infeasible case: leave as is (will not affect cost calc)
            pass
    # Determine open warehouses (those with positive assignment)
    for j in range(m):
        if remaining_cap[j] < warehouses[j]['capacity']:
            open_list[j] = 1
    # Compute total cost
    for j in range(m):
        if open_list[j]:
            total_cost += warehouses[j]['fixed_cost']
    for i in range(n):
        for j in range(m):
            total_cost += assignments[i][j] * customers[i]['costs'][j]
    return {
        "total_cost": total_cost,
        "warehouse_open": open_list,
        "assignments": assignments
    }
